'use strict';
const ratingCache=new Map(),ratingPriceChecks=new Map();let ratingRowsRef=null,ratingLoading=false;
function calculatePoliticianRating(person,records,prices,now=Date.now()){
 const today=new Date(now).toISOString().slice(0,10),cutoff=now-365*86400000,unique=new Map();
 for(const r of records){const d=disclosedDate(r);if(r.person!==person||r.type!=='Purchase'||!['Stock','ADR'].includes(r.asset)||r.quality==='User-provided'||!d||d>today||r.traded>today||Date.parse(r.traded)<cutoff)continue;const key=r.ticker+'|'+r.traded,old=unique.get(key);if(!old||d<disclosedDate(old))unique.set(key,r)}
 const benchmark=prices.SPY,calendar=Object.keys(benchmark?.closes||{}).filter(d=>d<=today&&d<=benchmark.asOf&&benchmark.closes[d]>0).sort(),samples=[];let pending=0,missing=0,stale=false;
 for(const r of unique.values()){const d=disclosedDate(r),start=calendar.findIndex(k=>k>d);if(start<0){if(calendar.length&&d>=calendar.at(-1))pending++;else missing++;continue}if(Date.parse(calendar[start])-Date.parse(d)>7*86400000){missing++;continue}if(start+20>=calendar.length){pending++;continue}const days=calendar.slice(start,start+21),p=prices[r.ticker];if(!p||p.error||p.asOf<days.at(-1)||days.some(k=>!(p.closes?.[k]>0))){missing++;continue}const entry=days[0],end=days.at(-1),gain=(p.closes[end]/p.closes[entry]-1)*100,excess=gain-(benchmark.closes[end]/benchmark.closes[entry]-1)*100;let peak=p.closes[entry],drawdown=0;for(const k of days){peak=Math.max(peak,p.closes[k]);drawdown=Math.min(drawdown,(p.closes[k]/peak-1)*100)}samples.push({ticker:r.ticker,traded:r.traded,disclosed:d,entry,end,gain,excess,drawdown,source:r.source});stale ||= !!p.stale||!!benchmark.stale;}
 const n=samples.length,mature=n+missing,coverage=mature?n/mature:0,tickers=new Set(samples.map(s=>s.ticker)).size,dates=new Set(samples.map(s=>s.traded)).size,median=medianTrack(samples.map(s=>s.excess)),win=n?100*samples.filter(s=>s.gain>0).length/n:null,beat=n?100*samples.filter(s=>s.excess>0).length/n:null,avg=n?samples.reduce((a,s)=>a+s.gain,0)/n:null;
 let reason=n<5?'Need 5 completed buys':tickers<2?'Need 2 different stocks':dates<3?'Need 3 purchase dates':coverage<.8?'Price coverage below 80%':null;
 const clamp=v=>Math.max(0,Math.min(100,v)),raw=n?.6*clamp(50+5*median)+.4*beat:50,score=reason?null:Math.round(50+(raw-50)*n/(n+10)),label=score===null?'Insufficient data':score>=65?'Strong':score>=55?'Positive':score>=45?'Mixed':'Weak';
 return {score,label,reason,n,total:unique.size,pending,missing,coverage,tickers,dates,median,win,beat,avg,stale,samples,asOf:calendar.at(-1)};
}
function politicianRating(person){if(ratingRowsRef!==signalData){ratingCache.clear();ratingRowsRef=signalData}const key=person+'|'+new Date().toISOString().slice(0,10);if(!ratingCache.has(key))ratingCache.set(key,calculatePoliticianRating(person,signalData,PRICES));return ratingCache.get(key)}
function ratingContents(person){const r=politicianRating(person);return `<b>Track ${r.score===null?'—':r.score+'/100'}</b><span>${r.label}</span><small>${r.n} scored buys${r.median===null?'':' · '+(r.median>=0?'+':'')+r.median.toFixed(1)+' pp vs SPY'}${r.stale?' · cached':''}</small>`}
function ratingBadge(person){return `<button class="track-rating" data-rating-grade="${politicianRating(person).label.toLowerCase().replaceAll(' ','-')}" data-rating="${esc(person)}" aria-label="${esc(person)} track-record rating and methodology" title="20 sessions after disclosure · tap for evidence">${ratingContents(person)}</button>`}
function refreshRatingBadges(){ratingCache.clear();document.querySelectorAll('[data-rating]').forEach(el=>{el.innerHTML=ratingContents(el.dataset.rating);el.dataset.ratingGrade=politicianRating(el.dataset.rating).label.toLowerCase().replaceAll(' ','-')})}
function showPoliticianRating(person){const r=politicianRating(person),fmt=v=>v===null?'—':(v>=0?'+':'')+v.toFixed(1)+'%',pp=r.median===null?'—':(r.median>=0?'+':'')+r.median.toFixed(1)+' pp';$('#detailContent').innerHTML=`<h2>${esc(person)}</h2><h3>Track record · ${r.score===null?'Unrated':r.score+'/100'} · ${r.label}</h3>${r.reason?`<p>${r.reason}. ${r.n} completed, benchmark-matched buys are currently available.</p>`:''}<div class="detail-grid"><div><small>Median vs SPY</small><strong>${pp}</strong></div><div><small>Beat SPY</small><strong>${r.beat===null?'—':r.beat.toFixed(0)+'%'}</strong></div><div><small>Average stock return</small><strong>${fmt(r.avg)}</strong></div><div><small>Positive-return rate</small><strong>${r.win===null?'—':r.win.toFixed(0)+'%'}</strong></div><div><small>Completed / eligible buys</small><strong>${r.n} / ${r.total}</strong></div><div><small>Priced mature windows</small><strong>${(100*r.coverage).toFixed(0)}%</strong></div></div><p>${r.tickers} stocks · ${r.dates} purchase dates · ${r.pending} pending windows · ${r.missing} missing histories. Benchmark through ${r.asOf?date(r.asOf):'unavailable'}${r.stale?' · cached prices':''}.</p><details><summary>How the score works</summary><p>Purchases in the past year, stocks and ADRs only. One observation per person, ticker and purchase date. Entry is the first SPY closing session strictly after disclosure; exit is 20 sessions later. Every stock close in that window must be available. No options, sales, exercises, ETFs or local imports.</p><p>Raw score = 60% × clamp(50 + 5 × median excess return in percentage points, 0, 100) + 40% × percentage of buys beating SPY. The final score is pulled toward 50 using n / (n + 10), where n is the completed sample. A rating requires 5 buys, 2 stocks, 3 purchase dates and 80% coverage of mature windows.</p><p>65–100 Strong · 55–64 Positive · 45–54 Mixed · 0–44 Weak. These are poor’s descriptive thresholds, not a validated prediction or probability. Overlapping trades are not independent. No dividends, costs, taxes or verified realized profits. Incomplete filings can bias results. Annual portfolio estimates do not enter the score.</p></details><details><summary>Scored purchases (${r.n})</summary>${r.samples.map(s=>`<p><b>${esc(s.ticker)}</b> · Bought ${esc(s.traded)} · Disclosed ${esc(s.disclosed)}<br>${esc(s.entry)} → ${esc(s.end)} · ${fmt(s.gain)} · ${s.excess>=0?'+':''}${s.excess.toFixed(1)} pp vs SPY<br><a href="${esc(s.source)}" target="_blank" rel="noopener">Source filing ↗</a></p>`).join('')||'<p>No completed samples.</p>'}</details>`;if(!$('#details').open)$('#details').showModal();}
// Fetch missing histories only for people in the current map or profile; calculations use no model calls.
async function ensurePoliticianRatingPrices(people){if(ratingLoading||typeof loadMarketPrices!=='function')return;ratingLoading=true;try{const names=new Set(people),cutoff=Date.now()-365*86400000,symbols=[...new Set(['SPY',...signalData.filter(r=>names.has(r.person)&&r.type==='Purchase'&&['Stock','ADR'].includes(r.asset)&&Date.parse(r.traded)>=cutoff).map(r=>r.ticker)])].filter(s=>/^[A-Z][A-Z0-9.-]{0,11}$/.test(s)&&(!ratingPriceChecks.has(s)||Date.now()-ratingPriceChecks.get(s)>15*60000));for(let i=0;i<symbols.length;i+=12){const batch=symbols.slice(i,i+12);batch.forEach(s=>ratingPriceChecks.set(s,Date.now()));await loadMarketPrices(batch);refreshRatingBadges();if(view!=='map'&&view!=='politicians')break}}finally{ratingLoading=false}}
if(typeof document!=='undefined')document.addEventListener('click',e=>{const b=e.target.closest('[data-rating]');if(b){e.preventDefault();e.stopPropagation();showPoliticianRating(b.dataset.rating)}});
